let measureCtx=null;
function textWidth(text=''){
  try{if(!measureCtx){const cv=document.createElement('canvas');measureCtx=cv.getContext('2d');measureCtx.font='12px "Malgun Gothic", "맑은 고딕", sans-serif'}return Math.ceil(measureCtx.measureText(String(text)).width)}catch{return String(text).length*8}
}
function actualSize(c){
  const txt=String(c.text||'');
  let w=c.w,h=c.h;
  if(w===-1){
    const tw=textWidth(txt);
    if(c.type==='text'||c.type==='link')w=Math.max(18,tw+4);
    else if(c.type==='check'||c.type==='radio')w=Math.max(20,tw+21);
    else if(c.type==='edit')w=120;
    else if(c.type==='combo')w=120;
    else if(c.type==='button')w=Math.max(44,tw+18);
    else w=70;
  }
  if(h===-1){h=['text','check','radio','link'].includes(c.type)?18:['edit','combo'].includes(c.type)?22:c.type==='button'?23:22}
  return {w:Math.max(8,Number(w)||8),h:Math.max(8,Number(h)||8)};
}
function displaySize(c){
  const sz=actualSize(c);
  return c.type==='group'?{w:sz.w+17,h:sz.h+(c.h===-1?16:14)}:sz;
}
function runtimeOuterSize(view=activeView()){
  const rt=runtimeMetrics(view);
  return state.activeType==='tab'?{w:rt.w,h:rt.h}:{w:rt.w+18,h:rt.h+66};
}
