  el.runtimeWindow.classList.toggle('dialog-preview',state.activeType==='dialog');
  el.runtimeWindow.style.width=`${outer.w}px`;el.runtimeWindow.style.height=`${outer.h}px`;el.runtimeWindow.style.transform=`scale(${sc})`;
